## 4. Mongoose ODM

Mongoose provides **schema validation**, **middleware**, **population**, and **TypeScript support** for MongoDB.

### Schema Definition

```typescript
import { Schema, model, Document, Types } from "mongoose";

interface IUser extends Document {
  name: string;
  email: string;
  passwordHash: string;
  role: "user" | "admin";
  profile: {
    bio?: string;
    avatar?: string;
  };
  tags: string[];
  createdAt: Date;
  updatedAt: Date;
}

const userSchema = new Schema<IUser>(
  {
    name: { type: String, required: [true, "Name is required"], trim: true, maxlength: 100 },
    email: {
      type: String,
      required: true,
      unique: true,
      lowercase: true,
      trim: true,
      match: [/^\S+@\S+\.\S+$/, "Invalid email format"],
    },
    passwordHash: { type: String, required: true, select: false },
    role: { type: String, enum: ["user", "admin"], default: "user" },
    profile: {
      bio: { type: String, maxlength: 500 },
      avatar: String,
    },
    tags: [{ type: String, trim: true }],
  },
  {
    timestamps: true,
    toJSON: {
      transform(_doc, ret) {
        delete ret.passwordHash;
        delete ret.__v;
        return ret;
      },
    },
  }
);

// Indexes
userSchema.index({ email: 1 });
userSchema.index({ name: "text", "profile.bio": "text" }); // text search
userSchema.index({ role: 1, createdAt: -1 });              // compound

export const User = model<IUser>("User", userSchema);
```

### Middleware (Hooks)

```typescript
import bcrypt from "bcrypt";

// Pre-save — hash password before saving
userSchema.pre("save", async function (next) {
  if (!this.isModified("passwordHash")) return next();
  this.passwordHash = await bcrypt.hash(this.passwordHash, 12);
  next();
});

// Post-save — log creation
userSchema.post("save", function (doc) {
  console.log(`User created: ${doc.email}`);
});
```

### Population (Joins)

```typescript
const postSchema = new Schema({
  title: String,
  author: { type: Types.ObjectId, ref: "User", required: true },
  comments: [{ type: Types.ObjectId, ref: "Comment" }],
});

// Populate author when fetching posts
const posts = await Post.find()
  .populate("author", "name email avatar")
  .populate({ path: "comments", options: { limit: 5, sort: { createdAt: -1 } } })
  .lean(); // returns plain JS objects — faster, no Mongoose overhead
```

### Mongoose CRUD with TypeScript

```typescript
// Create
const user = await User.create({ name: "Amit", email: "a@x.com", passwordHash: "plain" });

// Read
const users = await User.find({ role: "admin" })
  .select("name email")
  .sort({ createdAt: -1 })
  .limit(10)
  .lean();

// Update
const updated = await User.findByIdAndUpdate(
  id,
  { $set: { name: "New Name" } },
  { new: true, runValidators: true }
);

// Delete
await User.findByIdAndDelete(id);

// Upsert
await User.findOneAndUpdate(
  { email: "a@x.com" },
  { $set: { lastLogin: new Date() } },
  { upsert: true, new: true }
);
```

